const SET = new Set(WORDS.map((w) => w.replace(/ё/g, "е").toLowerCase()));

export function normalizeWord(raw: string): string {
  return raw.replace(/ё/g, "е").toLowerCase().trim();
}

export function isValidWord(raw: string): boolean {
  const w = normalizeWord(raw);
  return w.length >= 2 && SET.has(w);
}

/** Короткие слова для посадки в случайный трей (всегда есть слово). */
export const SEED_WORDS: readonly string[] = WORDS.filter((w) => w.length >= 3 && w.length <= 5);

function letterCounts(letters: string[]): Map<string, number> {
  const have = new Map<string, number>();
  for (const ch of letters) {
    const c = ch.toLowerCase().replace("ё", "е");
    if (!c) continue;
    have.set(c, (have.get(c) ?? 0) + 1);
  }
  return have;
}

function canBuild(word: string, have: Map<string, number>): boolean {
  const need = new Map<string, number>();
  for (const ch of word) need.set(ch, (need.get(ch) ?? 0) + 1);
  for (const [ch, n] of need) {
    if ((have.get(ch) ?? 0) < n) return false;
  }
  return true;
}

/** Есть ли в наборе букв хоть одно словарное слово (3–5). */
export function trayHasWord(letters: string[]): boolean {
  return findWordFromLetters(letters) !== null;
}

/** Самое длинное (до 5) слово, собираемое из букв. */
export function findWordFromLetters(letters: string[]): string | null {
  const have = letterCounts(letters);
  let best: string | null = null;
  for (const w of SEED_WORDS) {
    if (!canBuild(w, have)) continue;
    if (!best || w.length > best.length) best = w;
  }
  return best;
}

/** Seed-слово с пересечением со стеной (чтобы был удар). */
export function pickSeedWord(prefer: string[] = []): string {
  const wall = new Set(prefer.map((c) => c.toUpperCase().replace("Ё", "Е")).filter(Boolean));
  const withHits: string[] = [];
  const strong: string[] = [];
  for (const w of SEED_WORDS) {
    const u = w.toUpperCase().replace(/Ё/g, "Е");
    let hits = 0;
    for (const ch of u) if (wall.has(ch)) hits++;
    if (hits <= 0) continue;
    withHits.push(w);
    if (hits >= Math.min(2, u.length)) strong.push(w);
  }
  let pool = strong.length ? strong : withHits.length ? withHits : [...SEED_WORDS];
  const preferred = pool.filter((w) => w.length >= 4);
  if (preferred.length) pool = preferred;
  return pool[Math.floor(Math.random() * pool.length)] ?? "дом";
}

